// KNN 7x20 Direction Vote 3D
// KNN nearest-neighbour vote on next-bar direction, margin + disagreement channels

kIn = input(7, "K Neighbors", 1, 20, 1)
featLen = input(20, "Feature Length", 5, 40, 1)
poolLen = input(20, "Pool Length", 10, 60, 1)
mThresh = input(0.43, "Margin Threshold", 0.1, 1.0, 0.01)
sThresh = input(0.5, "Disagreement Threshold", 0.05, 2.0, 0.05)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Model calculations ────────────────────────────────────
// Feature type: close-to-close returns r(i) = (close(i)-close(i-1))/close(i-1)
ret = 0.0
if close[1] != 0 {
    ret := (close - close[1]) / close[1]
}

warmup = featLen + poolLen + 5
isReady = bar_index > warmup

// Euclidean distance pool: j = t-2 .. t-poolLen-1, feature window featLen
bestD0 = 999999.0
bestD1 = 999999.0
bestD2 = 999999.0
bestD3 = 999999.0
bestD4 = 999999.0
bestD5 = 999999.0
bestD6 = 999999.0
bestL0 = 0
bestL1 = 0
bestL2 = 0
bestL3 = 0
bestL4 = 0
bestL5 = 0
bestL6 = 0

d = 2
while d <= poolLen + 1 {
    sumSq = 0.0
    n = 0
    while n < featLen {
        a = ret[n]
        b = ret[d + n]
        diff = a - b
        sumSq := sumSq + diff * diff
        n := n + 1
    }
    dist = sqrt(sumSq)
    lbl = 0 - 1
    if close[d - 1] > close[d] {
        lbl := 1
    }
    if dist < bestD6 {
        if dist < bestD0 {
            bestD6 := bestD5
            bestL6 := bestL5
            bestD5 := bestD4
            bestL5 := bestL4
            bestD4 := bestD3
            bestL4 := bestL3
            bestD3 := bestD2
            bestL3 := bestL2
            bestD2 := bestD1
            bestL2 := bestL1
            bestD1 := bestD0
            bestL1 := bestL0
            bestD0 := dist
            bestL0 := lbl
        } else {
            if dist < bestD1 {
                bestD6 := bestD5
                bestL6 := bestL5
                bestD5 := bestD4
                bestL5 := bestL4
                bestD4 := bestD3
                bestL4 := bestL3
                bestD3 := bestD2
                bestL3 := bestL2
                bestD2 := bestD1
                bestL2 := bestL1
                bestD1 := dist
                bestL1 := lbl
            } else {
                if dist < bestD2 {
                    bestD6 := bestD5
                    bestL6 := bestL5
                    bestD5 := bestD4
                    bestL5 := bestL4
                    bestD4 := bestD3
                    bestL4 := bestL3
                    bestD3 := bestD2
                    bestL3 := bestL2
                    bestD2 := dist
                    bestL2 := lbl
                } else {
                    if dist < bestD3 {
                        bestD6 := bestD5
                        bestL6 := bestL5
                        bestD5 := bestD4
                        bestL5 := bestL4
                        bestD4 := bestD3
                        bestL4 := bestL3
                        bestD3 := dist
                        bestL3 := lbl
                    } else {
                        if dist < bestD4 {
                            bestD6 := bestD5
                            bestL6 := bestL5
                            bestD5 := bestD4
                            bestL5 := bestL4
                            bestD4 := dist
                            bestL4 := lbl
                        } else {
                            if dist < bestD5 {
                                bestD6 := bestD5
                                bestL6 := bestL5
                                bestD5 := dist
                                bestL5 := lbl
                            } else {
                                bestD6 := dist
                                bestL6 := lbl
                            }
                        }
                    }
                }
            }
        }
    }
    d := d + 1
}

// Channel 1 - Vote Margin M = (Up-Down)/7
upCount = 0
if bestL0 == 1 { upCount := upCount + 1 }
if bestL1 == 1 { upCount := upCount + 1 }
if bestL2 == 1 { upCount := upCount + 1 }
if bestL3 == 1 { upCount := upCount + 1 }
if bestL4 == 1 { upCount := upCount + 1 }
if bestL5 == 1 { upCount := upCount + 1 }
if bestL6 == 1 { upCount := upCount + 1 }
downCount = 7 - upCount
margin = (upCount - downCount) / 7.0

// Channel 2 - Neighbour Disagreement S = stdev(7 D) / mean(7 D)
meanD = (bestD0 + bestD1 + bestD2 + bestD3 + bestD4 + bestD5 + bestD6) / 7.0
v0 = (bestD0 - meanD) * (bestD0 - meanD)
v1 = (bestD1 - meanD) * (bestD1 - meanD)
v2 = (bestD2 - meanD) * (bestD2 - meanD)
v3 = (bestD3 - meanD) * (bestD3 - meanD)
v4 = (bestD4 - meanD) * (bestD4 - meanD)
v5 = (bestD5 - meanD) * (bestD5 - meanD)
v6 = (bestD6 - meanD) * (bestD6 - meanD)
sdD = sqrt((v0 + v1 + v2 + v3 + v4 + v5 + v6) / 7.0)
disagree = 0.0
if meanD > 0.000000001 {
    disagree := sdD / meanD
}

M = 0.0
S = 1.0
if isReady {
    M := margin
    S := disagree
}

// ─── Persistent state ──────────────────────────────────────
var lastBuy = 0
var lastSell = 0

// ─── Signal conditions: strong margin + low disagreement, edge-gated ──
Mprev = M[1]
Sprev = S[1]
buySig = isReady and M > mThresh and Mprev <= mThresh and S < sThresh
sellSig = isReady and M < (0 - mThresh) and Mprev >= (0 - mThresh) and S < sThresh

// ─── Signal markers ────────────────────────────────────────
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}
if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", markerSize, 0, "separate")
}
if sellSig {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", markerSize, 0, "separate")
}

// ─── Unconditional rendering ───────────────────────────────
plot(M, "Vote Margin", "#22cc88", 2, "separate")
plot(S, "Disagreement", "#ffaa33", 2, "separate")
hline(0.43, "#22cc8855", "separate")
hline(-0.43, "#ff447755", "separate")
hline(0.5, "#ffaa3355", "separate")
marginBars = M * 100 + close * 0.0 + bar_index * 0.0
disagreeRibbon = S * 100 + close * 0.0 + bar_index * 0.0
plot3d(marginBars, "Vote Margin Prism", "bars3d", "#22cc88", "separate")
plot3d(disagreeRibbon, "Disagreement Base", "ribbon", "#ffaa33", "separate", 1)

// Visible Value Terrain POC Model
// Volume profile from visible session: POC + value area, breakout signals.

Rows = input(24, "Rows", 10, 48, 1)
ValueAreaPercent = input(70, "Value Area %", 50, 90, 5)
UseVisibleSession = input(true, "Use Visible Session")
ExtendLines = input(true, "Extend Lines")
Show3D = input(true, "Show 3D")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Visible session range ─────────────────────────────────────────
maxVis = 250
fullLen = bar_index + 1
visLen = fullLen
if visLen > maxVis { visLen := maxVis }
if visLen < 20 { visLen := fullLen }
sessLen = 60
if UseVisibleSession { sessLen := visLen }
if sessLen > fullLen { sessLen := fullLen }
if sessLen < 1 { sessLen := 1 }

hh = highest(high, sessLen)
ll = lowest(low, sessLen)
rng = hh - ll
if rng <= 0 { rng := close * 0.01 }
binSize = rng / Rows

// ─── Persistent bins (reset each bar, refilled from visible bars) ─
var binVol = array()
var binsReady = false
if not binsReady {
    k = 0
    while k < 48 {
        array.push(binVol, 0.0)
        k := k + 1
    }
    binsReady := true
}

// Clear active rows
i = 0
while i < Rows {
    array.set(binVol, i, 0.0)
    i := i + 1
}

// Deposit each visible bar's volume into its hlc3 bin
totalSeen = 0.0
j = sessLen - 1
while j >= 0 {
    tp = (high[j] + low[j] + close[j]) / 3
    vv = volume[j]
    bi = floor((tp - ll) / rng * Rows)
    if bi < 0 { bi := 0 }
    if bi > Rows - 1 { bi := Rows - 1 }
    array.set(binVol, bi, array.get(binVol, bi) + vv)
    totalSeen := totalSeen + vv
    j := j - 1
}
totalVol = array.sum(binVol)
if totalVol <= 0 { totalVol := 1.0 }

// ─── Point of control ──────────────────────────────────────────────
pocBin = 0
pocVal = array.get(binVol, 0)
i = 1
while i < Rows {
    v = array.get(binVol, i)
    if v > pocVal {
        pocVal := v
        pocBin := i
    }
    i := i + 1
}
pocPrice = ll + (pocBin + 0.5) / Rows * rng
pocShare = pocVal / totalVol * 100

// ─── Value area: expand from POC ───────────────────────────────────
vaLow = pocBin
vaHigh = pocBin
accum = pocVal
target = totalVol * ValueAreaPercent / 100
guard = 0
while accum < target and guard < Rows {
    leftVal = 0 - 1.0
    if vaLow > 0 { leftVal := array.get(binVol, vaLow - 1) }
    rightVal = 0 - 1.0
    if vaHigh < Rows - 1 { rightVal := array.get(binVol, vaHigh + 1) }
    if rightVal >= leftVal and vaHigh < Rows - 1 {
        vaHigh := vaHigh + 1
        accum := accum + rightVal
    } else {
        if vaLow > 0 {
            vaLow := vaLow - 1
            accum := accum + leftVal
        }
    }
    guard := guard + 1
}
vahPrice = ll + (vaHigh + 1) / Rows * rng
valPrice = ll + vaLow / Rows * rng
vaWidth = vahPrice - valPrice
insideVA = close >= valPrice and close <= vahPrice
midVA = (vahPrice + valPrice) / 2
valueTerrain = (pocPrice + midVA + close) / 3

// ─── Signals: leaving value + POC cross + return ───────────────────
var wasInside = true
buySig = wasInside and not insideVA and close > vahPrice
sellSig = wasInside and not insideVA and close < valPrice
returnInside = insideVA and not wasInside
pocCrossUp = crossover(close, pocPrice)
pocCrossDown = crossunder(close, pocPrice)
pocAlert = (pocCrossUp or pocCrossDown) and not insideVA
if buySig { plotshape(bar_index, low, "Buy", "triangleup", "#22cc88") }
if sellSig { plotshape(bar_index, high, "Sell", "triangledown", "#ff4477") }
if pocAlert { plotshape(bar_index, close, "POC Cross", "diamond", "#ffd43b") }
if returnInside { plotshape(bar_index, close, "Back In Value", "circle", "#b48cff") }
wasInside := insideVA

// ─── 2D: same information when 3D is off ────────────────────────────
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
plot(valPrice, "VAL", "#ff4477", 1, "stepline")
plot(pocShare, "POC Share %", "#ffd43b", 1, "separate")
plot(vaWidth, "VA Width", "#4488ff", 1, "separate")

// Value zone shading (updated in place)
box.new(bar_index - sessLen + 1, vahPrice, bar_index, valPrice, "#4488ff", "rgba(68,136,255,0.12)", 1, "vaBox")
if insideVA { bgcolor("rgba(68,136,255,0.05)") }
if buySig { bgcolor("rgba(34,204,136,0.08)") }
if sellSig { bgcolor("rgba(255,68,119,0.08)") }

// ─── 3D: value sits as terrain, POC as labelled rail ───────────────
plot3d(valueTerrain, "Value Terrain", "manifold", "#4488ff", "3d", 0)
plot3d(pocPrice, "POC Rail Line", "line3d", "#ffd43b", "3d", 1)
if pocAlert { label3d(bar_index, pocPrice, "POC Rail", "#ffd43b", 1.0, 1, "3d") }

// Fix 1: var lvl = highest(high, 20) froze at bar 0 — changed to plain assignment recomputed every bar.
// Fix 2: close[-1] is a future leak — changed to close so breakout uses current bar only.
// Fix 3: plotshape(true, low, "Buy", shape.triangleup, color.green) is Pine signature — changed to Oak positional (bar_index, price, title, style, color).
// Fix 4: RSI oscillator in pane="3d" renders as spiky forest over price — changed to pane="separate".
len = input(20, "High Length", 1, 100, 1)
rsiLen = input(14, "RSI Length", 2, 100, 1)
osLvl = input(30, "Oversold Level", 1, 50, 1)
lvl = highest(high, len)
r = rsi(close, rsiLen)
buySig = close > lvl
osSig = crossover(r, osLvl)
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if osSig {
    plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
}
plot(r, "RSI", "#b48cff", 1)
hline(30, "#b48cff")
plot3d(r, "RSI", "surface", "#b48cff", "separate")
